#!/usr/bin/env python3
"""Small durable HTTP record service for the builder deployment slot."""

import os
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit


HOST = "0.0.0.0"
PORT = 8080
DATA_DIR = "/var/lib/builder-app"
DATABASE = os.path.join(DATA_DIR, "records.sqlite3")


class RecordHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def _send(self, status, body=b"", content_type=None):
        self.send_response(status)
        if content_type is not None:
            self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if body:
            self.wfile.write(body)

    def _record_id(self):
        path = urlsplit(self.path).path
        parts = path.split("/")
        if len(parts) != 3 or parts[1] != "records" or not parts[2]:
            return None
        try:
            return unquote(parts[2], errors="strict")
        except UnicodeDecodeError:
            return None

    def _read_body(self):
        value = self.headers.get("Content-Length")
        if value is None:
            return None
        try:
            length = int(value)
        except ValueError:
            return None
        if length < 0:
            return None
        return self.rfile.read(length)

    def do_GET(self):
        if urlsplit(self.path).path == "/health":
            self._send(200, b"ready", "text/plain")
            return

        record_id = self._record_id()
        if record_id is None:
            self._send(404)
            return

        with sqlite3.connect(DATABASE) as connection:
            row = connection.execute(
                "SELECT body FROM records WHERE id = ?", (record_id,)
            ).fetchone()
        if row is None:
            self._send(404)
        else:
            self._send(200, bytes(row[0]), "application/octet-stream")

    def do_PUT(self):
        record_id = self._record_id()
        if record_id is None:
            self._send(404)
            return

        body = self._read_body()
        if body is None:
            self._send(400)
            return

        with sqlite3.connect(DATABASE) as connection:
            connection.execute(
                "INSERT INTO records (id, body) VALUES (?, ?) "
                "ON CONFLICT(id) DO UPDATE SET body = excluded.body",
                (record_id, body),
            )
        self._send(204)

    def log_message(self, format, *args):
        print("%s - - [%s] %s" % (self.address_string(), self.log_date_time_string(), format % args), flush=True)


def main():
    os.makedirs(DATA_DIR, exist_ok=True)
    with sqlite3.connect(DATABASE) as connection:
        connection.execute("PRAGMA journal_mode = WAL")
        connection.execute("PRAGMA synchronous = FULL")
        connection.execute(
            "CREATE TABLE IF NOT EXISTS records "
            "(id TEXT PRIMARY KEY NOT NULL, body BLOB NOT NULL)"
        )

    server = ThreadingHTTPServer((HOST, PORT), RecordHandler)
    server.serve_forever()


if __name__ == "__main__":
    main()

